 48	function fakeRunner(responses: readonly CommandResult[]): { run: Runner; calls: string[][] } {
 49	  const calls: string[][] = [];
 50	  let index = 0;
 51	  const run: Runner = (argv) => {
 52	    calls.push([...argv]);
 53	    const response = responses[index];
 54	    if (response == null) throw new Error(`unscripted call ${index + 1}: ${argv.join(" ")}`);
 55	    index += 1;
 56	    return Promise.resolve(response);
 57	  };
 58	  return { run, calls };
 59	}
