 61	async function failureOf(attempt: Promise<unknown>): Promise<DispatchError> {
 62	  try {
 63	    await attempt;
 64	  } catch (error) {
 65	    if (error instanceof DispatchError) return error;
 66	    throw error;
 67	  }
 68	  throw new Error("expected the dispatch to fail");
 69	}
