 33	// The sandbox marker covers the whole invocation, so every subprocess takes an argv array.
 34	export const spawnRunner: Runner = async (argv, options) => {
 35	  let proc: Bun.Subprocess<"ignore", "pipe", "pipe">;
 36	  try {
 37	    proc = Bun.spawn([...argv], {
 38	      stdin: "ignore",
 39	      stdout: "pipe",
 40	      stderr: "pipe",
 41	      // Bun inherits this environment by default, so spreading it keeps that
 42	      // behavior while letting a caller add to it.
 43	      env: { ...process.env, ...options?.env },
 44	    });
 45	  } catch (error) {
 46	    // Spawning throws when the binary is missing, which would escape the
 47	    // DispatchError contract and lose the partial record with it.
 48	    const reason = error instanceof Error ? error.message : String(error);
 49	    return { code: 127, stdout: "", stderr: `${argv[0]}: ${reason}\n` };
 50	  }
 51	  const timer =
 52	    options?.timeoutMs == null
 53	      ? null
 54	      : setTimeout(() => {
 55	          proc.kill();
 56	        }, options.timeoutMs);
 57	  try {
 58	    const [stdout, stderr, code] = await Promise.all([
 59	      new Response(proc.stdout).text(),
 60	      new Response(proc.stderr).text(),
 61	      proc.exited,
 62	    ]);
 63	    // A signal is how the kill above shows up, and the process itself writes
 64	    // nothing to explain why it stopped.
 65	    if (options?.timeoutMs == null || proc.signalCode == null) return { code, stdout, stderr };
 66	    return {
 67	      code: code === 0 ? 124 : code,
 68	      stdout,
 69	      stderr: `${stderr}${argv[0]}: killed after ${options.timeoutMs}ms\n`,
 70	    };
 71	  } finally {
 72	    if (timer != null) clearTimeout(timer);
 73	  }
 74	};
