140	// herdr writes its JSON envelope on stderr, sometimes behind other output, so
141	// the last line is tried after the whole stream.
142	export function envelopeCode(stderr: string): string | null {
143	  const lastLine = stderr.split("\n").findLast((line) => line.trim() !== "");
144	  return readEnvelope(stderr) ?? (lastLine == null ? null : readEnvelope(lastLine));
145	}
146	
147	function readEnvelope(text: string): string | null {
148	  let json: unknown;
149	  try {
150	    json = JSON.parse(text);
151	  } catch {
152	    // This probes arbitrary stderr text for an envelope, so non-JSON input is
153	    // the ordinary case rather than a failure: it just means there is none.
154	    return null;
155	  }
156	  const parsed = ErrorEnvelope.safeParse(json);
157	  return parsed.success ? parsed.data.error.code : null;
158	}
