160	export function deriveName(branch: string, taken: ReadonlySet<string>): string {
161	  const slug = branch
162	    .toLowerCase()
163	    .replaceAll(/[^a-z0-9_-]/g, "-")
164	    .replaceAll(/-+/g, "-")
165	    .replace(/^[^a-z]+/, "")
166	    .slice(0, MAX_AGENT_NAME);
167	  const base = slug === "" ? "agent" : slug;
168	
169	  let candidate = base;
170	  for (let n = 2; taken.has(candidate); n += 1) {
171	    const suffix = `-${n}`;
172	    candidate = base.slice(0, MAX_AGENT_NAME - suffix.length) + suffix;
173	  }
174	  return candidate;
175	}
