177	export function taskSummary(prompt: string): string {
178	  // A prompt file often opens with a heading or a rule, so the summary is the
179	  // first line that still carries words once the markup is off the front.
180	  const line =
181	    prompt
182	      .split("\n")
183	      .map((entry) => entry.replace(/^[\s>#*+-]+/, "").trim())
184	      .find((entry) => /\w/.test(entry)) ?? "";
185	  return line.slice(0, MAX_TASK_SUMMARY);
186	}
