192	function decode<T>(
193	  schema: z.ZodType<T>,
194	  result: CommandResult,
195	  label: string,
196	  partial: DispatchRecord | null,
197	): T {
198	  let json: unknown;
199	  try {
200	    json = JSON.parse(result.stdout);
201	  } catch {
202	    throw new DispatchError(
203	      `${label} did not return JSON: ${result.stdout.slice(0, 200)}`,
204	      partial,
205	    );
206	  }
207	  const parsed = schema.safeParse(json);
208	  if (!parsed.success)
209	    throw new DispatchError(
210	      `${label} returned an unexpected shape: ${parsed.error.message}`,
211	      partial,
212	    );
213	  return parsed.data;
214	}
