222	async function required(
223	  run: Runner,
224	  argv: readonly string[],
225	  partial: DispatchRecord | null,
226	  options?: RunOptions,
227	): Promise<CommandResult> {
228	  const result = await run(argv, options);
229	  if (result.code !== 0)
230	    throw new DispatchError(
231	      result.stderr.trim() === "" ? `${argv.join(" ")} exited ${result.code}` : result.stderr,
232	      partial,
233	    );
234	  return result;
235	}
