246	// A base like origin/main needs its remote updated first. A local ref names no
247	// remote, and fetching one the repository does not have would fail the dispatch.
248	function baseRemote(remotes: ReadonlySet<string>, base: string): string | null {
249	  const candidate = base.split("/")[0];
250	  if (candidate == null || candidate === base) return null;
251	  return remotes.has(candidate) ? candidate : null;
252	}
