254	// The sandbox denies a session's writes to the shared .git/config, where `git
255	// push -u` records tracking, so record it here instead. herdr tracks the base,
256	// which would measure the session's branch against origin/main. Tracking is a
257	// convenience, so a failed write leaves herdr's and still starts the agent.
258	async function trackOrigin(
259	  run: Runner,
260	  remotes: ReadonlySet<string>,
261	  path: string,
262	  branch: string,
263	): Promise<void> {
264	  if (!remotes.has("origin")) return;
265	  const remote = await run(["git", "-C", path, "config", `branch.${branch}.remote`, "origin"]);
266	  if (remote.code !== 0) return;
267	  await run(["git", "-C", path, "config", `branch.${branch}.merge`, `refs/heads/${branch}`]);
268	}
