270	// GitHub over SSH signs with a key that may need a touch nobody is there to give, so
271	// fetch the same repository over HTTPS into the remote's own tracking refs.
272	export function fetchArgs(remote: string, url: string): string[] {
273	  const ssh = /^(?:git@github\.com:|ssh:\/\/git@github\.com\/)(.+?)(?:\.git)?\/?$/.exec(url.trim());
274	  if (ssh?.[1] == null) return [remote];
275	  return [`https://github.com/${ssh[1]}.git`, `+refs/heads/*:refs/remotes/${remote}/*`];
276	}
