278	// git worktree add leaves submodules empty and herdr runs no repository hook,
279	// so a checkout whose tooling links into them comes up broken. The agent can
280	// still repair it, so a failure is recorded rather than fatal.
281	async function initSubmodules(run: Runner, path: string): Promise<string | undefined> {
282	  if (!(await Bun.file(join(path, ".gitmodules")).exists())) return undefined;
283	  const result = await run(["git", "-C", path, "submodule", "update", "--init", "--recursive"], {
284	    timeoutMs: FETCH_TIMEOUT_MS,
285	    env: { GIT_TERMINAL_PROMPT: "0" },
286	  });
287	  if (result.code === 0) return undefined;
288	  return result.stderr.trim() === ""
289	    ? `git submodule update exited ${result.code}`
290	    : result.stderr.trim();
291	}
