297	// A derived name can be bound by another dispatch between the list above and
298	// this start, and herdr names that race. The worktree already exists by then,
299	// so the dispatch takes the next free name rather than leaving it without an
300	// agent. The replacement can lose the same race, so the retry is bounded. A
301	// name the caller asked for has no substitute.
302	async function startNamed(
303	  run: Runner,
304	  options: DispatchOptions,
305	  partial: DispatchRecord,
306	  name: string,
307	  attempt = 1,
308	): Promise<{ name: string; started: CommandResult }> {
309	  const started = await run([
310	    "herdr",
311	    "agent",
312	    "start",
313	    name,
314	    "--kind",
315	    "claude",
316	    "--pane",
317	    partial.pane,
318	  ]);
319	  if (
320	    options.name != null ||
321	    attempt >= NAME_ATTEMPTS ||
322	    envelopeCode(started.stderr) !== "agent_name_taken"
323	  )
324	    return { name, started };
325	
326	  const live = agentNames(await requiredJson(run, ["herdr", "agent", "list"], AgentList, partial));
327	  return startNamed(run, options, partial, deriveName(options.branch, live), attempt + 1);
328	}
