330	// agent prompt --wait does not track turns, so a startup turn still running
331	// would satisfy --until working and report work the agent never took. A
332	// submission from idle is what makes the observed transition this prompt's.
333	async function deliver(
334	  run: Runner,
335	  name: string,
336	  options: DispatchOptions,
337	  partial: DispatchRecord,
338	  started: CommandResult,
339	): Promise<boolean> {
340	  const info = decode(AgentStarted, started, "herdr agent start", partial);
341	  if (info.result.agent.agent_status !== "idle") {
342	    const settled = await run([
343	      "herdr",
344	      "agent",
345	      "wait",
346	      name,
347	      "--until",
348	      "idle",
349	      "--timeout",
350	      String(options.timeout),
351	    ]);
352	    if (settled.code !== 0) return false;
353	  }
354	
355	  const submitted = await run([
356	    "herdr",
357	    "agent",
358	    "prompt",
359	    name,
360	    options.prompt,
361	    "--wait",
362	    "--until",
363	    "working",
364	    "--timeout",
365	    String(options.timeout),
366	  ]);
367	  // Neither tolerated code confirms delivery. agent_prompt_stalled means
368	  // nothing was observed after the paste, which a fast turn and a lost Enter
369	  // both produce. A timeout under --until working means the agent reached
370	  // blocked and stayed there, where a dialog may be holding the prompt.
371	  if (fatal(submitted, "timeout", "agent_prompt_stalled"))
372	    throw new DispatchError(submitted.stderr, partial);
373	  return submitted.code === 0;
374	}
